	var com_android_AndroidNetwork_default = class {
		static id = "com.android.AndroidNetwork";
		async addSimpleTrack(ctx, trackName, tableOrQuery, columns) {
			await addDebugSliceTrack({
				trace: ctx,
				data: {
					sqlSource: `SELECT ${columns.join(",")} FROM ${tableOrQuery}`,
					columns
				},
				title: trackName,
				columns: {
					ts: columns[0],
					dur: columns[1],
					name: columns[2]
				},
				rawColumns: columns.slice(2)
			});
		}
		async onTraceLoad(ctx) {
			ctx.commands.registerCommand({
				id: "com.android.AddBatteryEventsTrack",
				name: "Add track: battery events",
				callback: async (trackNameArg) => {
					const trackName = typeof trackNameArg === "string" ? trackNameArg : await ctx.omnibox.prompt("Battery Track");
					if (!trackName) return;
					await ctx.engine.query(`SELECT IMPORT('android.battery_stats');`);
					await this.addSimpleTrack(ctx, trackName, `(SELECT *
            FROM android_battery_stats_event_slices
            WHERE track_name = "${trackName}")`, [
						"ts",
						"dur",
						"str_value",
						"int_value"
					]);
				}
			});
			ctx.commands.registerCommand({
				id: "com.android.AddNetworkActivityTrack",
				name: "Add track: network activity",
				callback: async (groupByArg, filterArg, trackNameArg) => {
					const groupby = typeof groupByArg === "string" ? groupByArg : await ctx.omnibox.prompt("Group by", "package_name");
					if (groupby === void 0) return;
					const filter = typeof filterArg === "string" ? filterArg : await ctx.omnibox.prompt("Filter", "TRUE");
					if (filter === void 0) return;
					const trackName = typeof trackNameArg === "string" ? trackNameArg : "Network Activity";
					const suffix = (/* @__PURE__ */ new Date()).getTime();
					await ctx.engine.query(`
          SELECT RUN_METRIC(
            'android/network_activity_template.sql',
            'view_name', 'android_network_activity_${suffix}',
            'group_by',  '${groupby}',
            'filter',    '${filter}',
            'idle_ns',   '10e9',
            'quant_ns',  '3e9'
          );
        `);
					const groupCols = groupby.replaceAll(" ", "").split(",");
					await this.addSimpleTrack(ctx, trackName, `android_network_activity_${suffix}`, [
						"ts",
						"dur",
						...groupCols,
						"packet_length",
						"packet_count"
					]);
				}
			});
		}
	};
