	function journald() {
		const settings = {
			minPrio: new Dropdown({
				title: "Minimum syslog priority",
				options: MIN_PRIO_OPTIONS,
				defaultValue: 7
			}),
			identifiers: new Textarea({
				title: "Process name (SYSLOG_IDENTIFIER) to record",
				placeholder: "One identifier per line\nsshd\nmy-service"
			}),
			units: new Textarea({
				title: "systemd units to record",
				placeholder: "One unit per line\nsystemd-journald.service\nuser@1000.service"
			})
		};
		return {
			id: "systemd_journald",
			title: "Journald log messages",
			description: "Records log messages from systemd-journald.",
			supportedPlatforms: ["LINUX"],
			settings,
			genConfig(tc) {
				const ds = tc.addDataSource(JOURNALD_DS);
				const journaldConfig = ds.journaldConfig ??= {};
				journaldConfig.minPrio = settings.minPrio.value;
				const identifiers = settings.identifiers.text.split("\n").map((line) => line.trim()).filter((line) => line.length > 0);
				if (identifiers.length > 0) journaldConfig.filterIdentifiers = identifiers;
				const units = settings.units.text.split("\n").map((line) => line.trim()).filter((line) => line.length > 0);
				if (units.length > 0) journaldConfig.filterUnits = units;
			}
		};
	}
