	async function runQueryForMcp(engine, query) {
		return resultToJson(await engine.query(query));
	}
	async function resultToJson(result) {
		const columns = result.columns();
		const rows = [];
		for (const it = result.iter({}); it.valid(); it.next()) {
			if (rows.length > 5e3) throw new Error("Query returned too many results, max 5000 rows. Results should be aggregates rather than raw data.");
			const row = {};
			for (const name of columns) {
				let value = it.get(name);
				if (typeof value === "bigint") value = Number(value);
				row[name] = value;
			}
			rows.push(row);
		}
		return JSON.stringify(rows);
	}
