			this.assertCurrent(generation);
			if (!this.ctx.getTrace() || scenes.length === 0) return;
			const sceneTypes = new Set(scenes.map((s) => s.type));
			const allInstructions = [];
			sceneTypes.forEach((sceneType) => {
				const instructions = SCENE_PIN_MAPPING[sceneType];
				if (instructions) instructions.forEach((inst) => {
					if (!allInstructions.some((i) => i.pattern === inst.pattern)) allInstructions.push(localizeScenePinInstruction(inst));
				});
			});
			if (allInstructions.length === 0) return;
			const activeProcesses = scenes.filter((s) => s.appPackage).map((s) => ({
				processName: s.appPackage,
				frameCount: 1
			}));
			this.debugLog("Auto-pinning tracks for scenes:", sceneTypes, "with", allInstructions.length, "instructions");
			await this.ctx.pinTracksFromInstructions(allInstructions, activeProcesses, () => this.isCurrent(generation));
			this.assertCurrent(generation);
