	function generateSampleItems() {
		const prefixes = [
			"dev.perfetto",
			"com.android",
			"org.chromium",
			"v8",
			"sys",
			"gpu"
		];
		const words1 = [
			"Gpu",
			"Render",
			"Device",
			"Memory",
			"Texture",
			"Shader",
			"Buffer",
			"Queue",
			"Async",
			"Direct",
			"Shared",
			"Virtual",
			"Global",
			"Frame",
			"Slice",
			"Track",
			"XML",
			"HTTP",
			"JSON",
			"IPC"
		];
		const words2 = [
			"Compute",
			"Command",
			"Allocator",
			"Context",
			"Manager",
			"Dispatcher",
			"Session",
			"Worker",
			"Scheduler",
			"Parser",
			"Serializer",
			"Controller",
			"Handler",
			"Engine"
		];
		const words3 = [
			"Pipeline",
			"Encoder",
			"Pool",
			"Cache",
			"Registry",
			"Listener",
			"Service",
			"Proxy",
			"Wrapper",
			"Channel",
			"Stream"
		];
		const items = [];
		let idCounter = 1;
		function toCamelCase(words) {
			return words[0].toLowerCase() + words.slice(1).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
		}
		function toPascalCase(words) {
			return words.map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
		}
		function toSnakeCase(words) {
			return words.map((w) => w.toLowerCase()).join("_");
		}
		function toKebabCase(words) {
			return words.map((w) => w.toLowerCase()).join("-");
		}
		for (const w1 of words1) for (const w2 of words2) for (const w3 of words3.slice(0, 3)) {
			const parts = [
				w1,
				w2,
				w3
			];
			items.push({
				id: String(idCounter++),
				name: toPascalCase(parts),
				category: "PascalCase"
			});
			items.push({
				id: String(idCounter++),
				name: toCamelCase(parts),
				category: "camelCase"
			});
			items.push({
				id: String(idCounter++),
				name: toSnakeCase(parts),
				category: "snake_case"
			});
			const prefix = prefixes[idCounter % prefixes.length];
			items.push({
				id: String(idCounter++),
				name: `${prefix}.${toPascalCase(parts)}`,
				category: "Dotted"
			});
			if (idCounter % 5 === 0) items.push({
				id: String(idCounter++),
				name: toKebabCase(parts),
				category: "kebab-case"
			});
		}
		return items;
	}
