	function generateNormalData(count, mean, stdDev, integer = false) {
		const data = [];
		for (let i = 0; i < count; i++) {
			const u1 = Math.random();
			const u2 = Math.random();
			const v = mean + Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2) * stdDev;
			data.push(integer ? Math.round(v) : v);
		}
		return data;
	}
